use super::{adjust_indent,handle_enter,parse_list_prefix,MetadataOverlay};use crate::types::{LineMetadata,ListType};use std::ops::Range;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub struct Selection{pub anchor:usize,pub caret:usize}impl Selection{pub fn range(self)->Range<usize>{self.anchor.min(self.caret)..self.anchor.max(self.caret)}pub fn is_empty(self)->bool{self.anchor==self.caret}}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct DocumentSnapshot{pub text:String,pub metadata:Vec<LineMetadata>,pub cursor:usize,pub selection_anchor:usize}
#[derive(Debug,Clone)]pub struct EditorBuffer{text:String,metadata:MetadataOverlay,cursor:usize,anchor:usize,undo:Vec<DocumentSnapshot>,redo:Vec<DocumentSnapshot>}
impl Default for EditorBuffer{fn default()->Self{Self::new("")}}impl EditorBuffer{pub fn new(text:impl Into<String>)->Self{let text=text.into();Self{text:text.clone(),metadata:MetadataOverlay::new(lines(&text)),cursor:0,anchor:0,undo:Vec::new(),redo:Vec::new()}}pub fn from_parts(text:impl Into<String>,metadata:Vec<LineMetadata>,cursor:usize)->Self{let text=text.into();let mut m=MetadataOverlay::from_lines(metadata);m.sync_to_line_count(lines(&text));let cursor=boundary(&text,cursor);Self{text,metadata:m,cursor,anchor:cursor,undo:Vec::new(),redo:Vec::new()}}pub fn text(&self)->&str{&self.text}pub fn metadata(&self)->&[LineMetadata]{self.metadata.as_slice()}pub fn cursor(&self)->usize{self.cursor}pub fn selection(&self)->Selection{Selection{anchor:self.anchor,caret:self.cursor}}pub fn line_count(&self)->usize{lines(&self.text)}pub fn line_of(&self,p:usize)->usize{self.text[..boundary(&self.text,p)].bytes().filter(|b|*b==b'\n').count()}pub fn column_of(&self,p:usize)->usize{let p=boundary(&self.text,p);let s=self.text[..p].rfind('\n').map_or(0,|i|i+1);self.text[s..p].chars().count()}pub fn set_cursor(&mut self,p:usize,extend:bool){let p=boundary(&self.text,p);if !extend{self.anchor=p}self.cursor=p}pub fn set_selection(&mut self,a:usize,c:usize){self.anchor=boundary(&self.text,a);self.cursor=boundary(&self.text,c)}pub fn snapshot(&self)->DocumentSnapshot{DocumentSnapshot{text:self.text.clone(),metadata:self.metadata.as_slice().to_vec(),cursor:self.cursor,selection_anchor:self.anchor}}pub fn restore(&mut self,s:DocumentSnapshot){self.text=s.text;self.metadata=MetadataOverlay::from_lines(s.metadata);self.metadata.sync_to_line_count(lines(&self.text));self.cursor=boundary(&self.text,s.cursor);self.anchor=boundary(&self.text,s.selection_anchor)}pub fn current_line(&self)->&str{self.text.split('\n').nth(self.line_of(self.cursor)).unwrap_or("").trim_end_matches('\r')}pub fn selected_line_range(&self)->(usize,usize){let r=self.selection().range();(self.line_of(r.start),self.line_of(if r.is_empty(){r.start}else{r.end-1}))}
pub fn insert_text(&mut self,s:&str){let r=self.selection().range();if !r.is_empty(){self.replace_range(r,s);return}if s.is_empty(){return}self.edit();let line=self.line_of(r.start);self.text.replace_range(r.clone(),s);let n=s.bytes().filter(|b|*b==b'\n').count();if n>0{self.metadata.on_insert(line,n)}self.metadata.sync_to_line_count(lines(&self.text));self.cursor=boundary(&self.text,r.start+s.len());self.anchor=self.cursor;self.finish()}pub fn replace_range(&mut self,r:Range<usize>,s:&str){let a=boundary(&self.text,r.start);let b=boundary(&self.text,r.end).max(a);if a==b&&s.is_empty(){return}self.edit();let line=self.line_of(a);let deleted=self.text[a..b].bytes().filter(|x|*x==b'\n').count();self.text.replace_range(a..b,s);if deleted>0{self.metadata.on_delete(line,deleted)}let added=s.bytes().filter(|x|*x==b'\n').count();if added>0{self.metadata.on_insert(line,added)}self.metadata.sync_to_line_count(lines(&self.text));self.cursor=boundary(&self.text,a+s.len());self.anchor=self.cursor;self.finish()}pub fn delete_backward(&mut self){let r=self.selection().range();if !r.is_empty(){self.replace_range(r,"")}else if self.cursor>0{let a=prev(&self.text,self.cursor);self.replace_range(a..self.cursor,"")}}pub fn delete_forward(&mut self){let r=self.selection().range();if !r.is_empty(){self.replace_range(r,"")}else if self.cursor<self.text.len(){let b=next(&self.text,self.cursor);self.replace_range(self.cursor..b,"")}}pub fn apply_colour(&mut self,c:crate::types::LineColour){let(a,b)=self.selected_line_range();self.edit();self.metadata.apply_colour(a,b,c);self.finish()}pub fn toggle_checkbox(&mut self,line:usize)->Option<bool>{self.edit();let r=self.metadata.toggle_checked(line);self.finish();r}pub fn recognise_list_prefixes(&mut self,w:usize){self.edit();for(i,l)in self.text.split('\n').enumerate(){if let Some(p)=parse_list_prefix(l,w){if let Some(m)=self.metadata.get_mut(i){m.list_type=p.list_type;m.indent=p.indent;m.checked=p.checked}}}self.finish()}pub fn handle_enter(&mut self,w:usize){let line=self.current_line().to_owned();let i=self.line_of(self.cursor);let m=self.metadata.get(i).cloned().or_else(||parse_list_prefix(&line,w).map(|p|LineMetadata{list_type:p.list_type,indent:p.indent,checked:p.checked,..LineMetadata::default()})).unwrap_or_default();let result=handle_enter(&line,&m);self.insert_text("\n");if let Some(n)=self.metadata.get_mut(i+1){*n=result.next_metadata}if result.exits_list{if let Some(n)=self.metadata.get_mut(i){n.list_type=ListType::None;n.indent=0;n.checked=false}}}pub fn adjust_indent(&mut self,up:bool){let i=self.line_of(self.cursor);self.edit();if let Some(m)=self.metadata.get_mut(i){adjust_indent(m,up)}self.finish()}pub fn undo(&mut self)->bool{let Some(s)=self.undo.pop()else{return false};self.redo.push(self.snapshot());self.restore(s);true}pub fn redo(&mut self)->bool{let Some(s)=self.redo.pop()else{return false};self.undo.push(self.snapshot());self.restore(s);true}fn edit(&mut self){self.undo.push(self.snapshot());if self.undo.len()>200{self.undo.remove(0)}self.redo.clear()}fn finish(&mut self){if self.undo.last().is_some_and(|s|s==&self.snapshot()){self.undo.pop();}}}
fn lines(s:&str)->usize{s.split('\n').count().max(1)}fn boundary(s:&str,p:usize)->usize{let mut p=p.min(s.len());while p>0&&!s.is_char_boundary(p){p-=1}p}fn prev(s:&str,p:usize)->usize{boundary(s,p.saturating_sub(1))}fn next(s:&str,p:usize)->usize{let p=boundary(s,p);p+s[p..].chars().next().map_or(0,char::len_utf8)}
